/// Central transaction record aggregating all line items, capturing buyer,
/// financial totals, and overall fulfillment status including aggregate
/// delivery milestones.
///
/// Orders represent the core purchase event in the ecommerce platform,
/// linking a customer to their selected products via order items. Each order
/// contains multiple items potentially from different sellers, with a
/// combined total price and an overall fulfillment status derived from
/// individual item statuses.
///
/// @namespace ecommerce_mall_orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_orders {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Links to the customer account that placed this order.
  ///
  /// This foreign key ensures orders can always be traced back to their
  /// originating customer for order history and account management purposes.
  ecommerce_mall_customer_id String @db.Uuid

  /// References the shipping address used for this order at checkout.
  ///
  /// This frozen address preserves the delivery destination even if the
  /// customer later modifies their address book.
  ecommerce_mall_shipping_address_id String @db.Uuid

  /// Total financial value of all order items combined.
  ///
  /// Calculated as the sum of all item prices at the time of checkout to
  /// provide a snapshot of the order cost.
  total_price Float @db.DoublePrecision

  /// Overall fulfillment state of the entire order.
  ///
  /// Values include: paid, shipped, delivered, cancelled, refunded,
  /// partially_completed. This aggregate status is derived from the statuses
  /// of individual order items.
  status String

  /// Timestamp when the order was initially created.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the most recent order modification.
  ///
  /// Updated whenever order status changes or associated order items receive
  /// updates such as payment confirmation, shipment dispatch, or refund
  /// processing.
  updated_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  customer ecommerce_mall_customers @relation(fields: [ecommerce_mall_customer_id], references: [id], onDelete: Cascade)
  shippingAddress ecommerce_mall_shipping_addresses @relation(fields: [ecommerce_mall_shipping_address_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  orderReviews ecommerce_mall_reviews[]
  orderItems ecommerce_mall_order_items[]
  shipments ecommerce_mall_shipments[]
  orderRefundRequests ecommerce_mall_refund_requests[]

  //----
  // INDEXES
  //----
  @@index([ecommerce_mall_shipping_address_id])
  @@index([ecommerce_mall_customer_id, created_at])
}

/// Individual line items within an order, capturing purchased variant
/// details and per-item fulfillment states.
///
/// Represents a specific quantity of a variant purchased in an order.
/// Captures the snapshot of the variant's metadata at the time of purchase
/// to ensure data immutability. Tracks independent fulfillment statuses
/// (e.g., paid, shipped, delivered, cancelled, refunded) which aggregate
/// into the total order status.
///
/// @namespace ecommerce_mall_orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_order_items {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Links the order item to the overarching transaction record in the order.
  ecommerce_order_id String @db.Uuid

  /// Identifies the specific product variant (SKU) that was purchased.
  ecommerce_product_variant_id String @db.Uuid

  /// Stores the seller ID at the time of purchase to provide historical
  /// contact and storefront details for dispute resolution.
  ecommerce_seller_id String @db.Uuid

  /// The title of the variant at the time of purchase.
  purchased_variant_name String

  /// The Stock Keeping Unit identifier of the variant at the time of purchase.
  purchased_sku String

  /// The unit price of the variant at the time the order was placed.
  purchased_price Float @db.DoublePrecision

  /// The name of the shop/seller at the time of purchase.
  purchased_seller_name String

  /// The specific option combinations (e.g., size, color) purchased as a
  /// string.
  purchased_options String

  /// The quantity of the variant included in the order.
  quantity Int @db.Integer

  /// Current fulfillment status of the item (e.g., paid, shipped, delivered,
  /// cancelled, refunded).
  status String

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record last update timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  order ecommerce_mall_orders @relation(fields: [ecommerce_order_id], references: [id], onDelete: Cascade)
  productVariant ecommerce_mall_product_variants @relation(fields: [ecommerce_product_variant_id], references: [id], onDelete: Cascade)
  seller ecommerce_mall_sellers @relation(fields: [ecommerce_seller_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  shipmentItems ecommerce_mall_shipment_items[]
  cancellationRequest ecommerce_mall_cancellation_requests?
  itemRefundRequests ecommerce_mall_refund_requests[]
  orderItemSnapshots ecommerce_mall_order_item_snapshots[]

